#!/usr/bin/env python3
"""orders_export pipeline — generated by etl-generator from orders_export.etlspec.yaml.

Regenerate from the spec rather than editing transform logic by hand;
hand-edits and the spec will otherwise drift apart.
Error codes reference the ETL Failure-Mode Taxonomy v0.1.

Authored in UNATTENDED mode: `ask`-class decisions were resolved against the
supplied target sample and are listed under review_required in the spec.
"""
import argparse
import etl_runtime as rt

# ---- Resolved configuration (from orders_export.etlspec.yaml — edit the spec, not this) ----
CONFIG = {
    "name": "orders_export",
    "spec_version": "0.1",                       # etlspec format version (manifest, ERR-06)
    "generator_version": "etl-generator/0.1",    # what generated this pipeline (ERR-06)
    "encoding": "utf-8",
    "delimiter": ",",
    "quotechar": '"',
    "expected_columns": ["order_id", "customer", "amt", "order_date", "active", "zip", "notes"],
    "output_columns": ["order_id", "customer_name", "amount", "order_date",
                       "is_active", "postal_code", "notes"],
    "policies": {
        "unicode_normalization": "NFC",          # ENC-03
        "strip_control_chars": True,             # ENC-04
        "normalize_unicode_whitespace": True,    # ENC-05
        "trim_whitespace": True,                 # NUL-02
        "empty_string_is_null": True,            # NUL-01 (unconfirmed; output-invariant here)
        "null_propagation": "sql",               # NUL-05
        "datetime_rendering": "iso8601",         # TYP-05
        "error_disposition": "quarantine",       # ERR-01
        "error_budget": {"percent": 5, "min_rows": 100},  # ERR-02
        "duplicate_rows": "keep",                # STR-05: keep-and-report exact duplicates
        "sentinels": {"notes": ["N/A"]},         # NUL-03: applied during null resolution
    },
}

# STR-06: confirmed non-data footer markers (matched on the not-null-enforced order_id).
_FOOTER_ORDER_IDS = {"total"}


def transform_row(row, rt_ctx):
    """Map one cleaned input row -> output row. Raise rt.RowError to reject the row,
    or rt.SkipRow to exclude a non-data row per an explicit spec decision.

    `row` values arrive already text-cleaned and null-resolved per policy
    (ENC-03/04/05, NUL-01/02/03 applied and counted by the runtime).
    """
    # STR-06: drop the footer/total row (7 fields, so not ragged) — explicit, counted.
    oid = row["order_id"]
    if oid is not None and oid.strip().lower() in _FOOTER_ORDER_IDS:
        raise rt.SkipRow("STR-06", "footer/total row")

    out = {}
    # order_id <- order_id  [TYP-07: kept as string, uniform 8-digit — detected-confirmed]
    out["order_id"] = rt.not_null(row["order_id"], "order_id")
    # customer_name <- customer  [ENC-06: opt-in mojibake repair — unconfirmed, matches target]
    out["customer_name"] = rt.not_null(
        rt.repair_mojibake(row["customer"], "customer", report=rt_ctx), "customer")
    # amount <- amt  [TYP-01: strip $/commas, (n)=negative; scale 2 — detected-confirmed]
    out["amount"] = rt.to_decimal(row["amt"], "amt", thousands_sep=",",
                                  currency=True, accounting_negative=True, scale=2)
    # order_date <- order_date  [TYP-03: MDY — detected-confirmed from target]
    out["order_date"] = rt.to_date(row["order_date"], "order_date", formats=["%m/%d/%Y"])
    # is_active <- active  [TYP-06: Y/N vocabulary — detected-confirmed]
    out["is_active"] = rt.to_bool(row["active"], "active",
                                  mapping={"Y": True, "N": False}, report=rt_ctx)
    # postal_code <- zip  [TYP-07: string, leading zeros present; TYP-11 length check]
    out["postal_code"] = rt.check_length(row["zip"], "zip", max_length=10)
    # notes <- notes  [NUL-03: 'N/A' sentinel + empty/whitespace -> null, resolved by runtime]
    out["notes"] = row["notes"]
    return out


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("input")
    p.add_argument("--out-dir", default="./etl_out")
    args = p.parse_args()
    result = rt.run_pipeline(
        input_path=args.input,
        out_dir=args.out_dir,
        config=CONFIG,
        transform_row=transform_row,
    )
    raise SystemExit(result.exit_code)


if __name__ == "__main__":
    main()
